def second_largest(nums):
    # Initialisation des variables pour stocker les deux plus grands nombres distincts
    max1 = float('-inf')
    max2 = float('-inf')

    # Parcours de la liste pour trouver les deux plus grands nombres distincts
    for num in nums:
        if num > max1:
            max2 = max1
            max1 = num
        elif max1 > num > max2:
            max2 = num

    # Vérification si il existe vraiment deux plus grands nombres distincts
    if max2 == float('-inf'):
        return None
    else:
        return max2
```

