def title_case(s):
    if not s:
        return ""

    words = s.split()
    result = []

    for word in words:
        if word.lower() in {"a", "le", "la", "et", "du", "des"} and len(word) > 3:
            result.append(word)
        else:
            result.append(word.capitalize())

    return ' '.join(result)
```

