def dedupe_keep_last(items):
    seen = set()
    result = []
    for item in reversed(items):
        if item not in seen:
            seen.add(item)
            result.insert(0, item)  # Ajoutez au début de la liste pour maintenir l'ordre original
    return result[::-1]
